"""Build a small provenance registry; never publish extracted source contents."""
from pathlib import Path
import hashlib
import json

ROOT=Path(__file__).resolve().parents[1]
assets=json.loads((ROOT/'research/symbols/text-assets.json').read_text(encoding='utf-8'))

def source(name, member, bundle='share'):
    found=[a for a in assets if a['name']==name+'.lua' and Path(a['bundle']).stem==bundle]
    if len(found)!=1:raise ValueError((name,len(found)))
    a=found[0]
    digest=hashlib.sha256((ROOT/a['output']).read_bytes()).hexdigest()
    if digest!=a['sha256']:raise ValueError('Original source fingerprint changed: '+name)
    return {'module':name,'member':member,'bundle':a['bundle'],'sha256':digest,'privateSourcePath':a['output']}

